def require(ok, message):
    if not ok:
        raise ValueError(message)


def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def encoded(value):
    return (json.dumps(value, indent=2, ensure_ascii=False, allow_nan=False)+'\n').encode()


def load_sources(root):
    data, pins = {}, {}
    for key, pin in PINS.items():
        path = Path(pin['path'])
        if not path.is_absolute():
            path = root/path
        raw = path.read_bytes()
        require(digest(raw) == pin['sha256'], 'Source SHA256 mismatch: '+key)
        data[key] = json.loads(raw)
        pins[key] = {**pin, 'bytes': len(raw)}
    return data, pins


def evidence(data, key, url, fragments):
    blocks = '\n'.join(b.get('text','') for b in data[key]['content']).split('--------------------------------------------------------------------------------')
    require(len([b for b in blocks if '('+url+')' in b and all(f in b for f in fragments)]) == 1,
            'Missing/ambiguous URL-bound evidence: '+url)


def definition(item, h, name, kind, description):
    require(item['hash'] == h and item['itemType'] == 19
            and item['displayProperties']['name'] == name
            and item['itemTypeDisplayName'] == kind
            and item['displayProperties']['description'] == description
            and not item['redacted'] and not item['blacklisted']
            and not item['plug']['isDummyPlug'], 'Exact tracking definition mismatch: '+str(h))
    return {'hash': h, 'name': name, 'itemType': 19, 'itemTypeDisplayName': kind,
            'description': description, 'plugCategoryHash': item['plug']['plugCategoryHash'],
            'plugCategoryIdentifier': item['plug']['plugCategoryIdentifier']}


def validate(data):
    selected, catalog = data['selected'], data['catalog']
    require(len(selected) == len(catalog) == 63
            and len({w['id'] for w in selected}) == 63
            and len({w['bungieHash'] for w in selected}) == 63,
            'Expected 63 unique exact selected hashes')
    cat = {w['id']: w for w in catalog}
    require(set(cat) == {w['id'] for w in selected}, 'Catalog selection drift')
    response = data['manifest']
    path = '/common/destiny2_content/json/en/DestinyInventoryItemDefinition-'+SUFFIX
    pool_path = path.replace('DestinyInventoryItemDefinition-', 'DestinyPlugSetDefinition-')
    require(response['ErrorCode'] == 1 and response['Response']['version'] == VERSION
            and response['Response']['jsonWorldComponentContentPaths']['en']['DestinyInventoryItemDefinition'] == path
            and response['Response']['jsonWorldComponentContentPaths']['en']['DestinyPlugSetDefinition'] == pool_path,
            'Official matching manifest components drift')
    prov = data['w40Provenance']
    require(prov['manifest'] == {'version':VERSION,'path':path}
            and prov['cachedInventorySha256'] == PINS['inventory']['sha256']
            and prov['source'] == 'https://www.bungie.net'+path, 'Selected provenance mismatch')
    inv, pools = data['inventory'], data['plugSets']
    defs = [definition(inv[str(BASE)], BASE, 'Tracking Module', 'Trait',
                      'Adds tracking capability to rockets. Locks onto targets when aiming down sights.'),
            definition(inv[str(ENHANCED)], ENHANCED, 'Tracking Module', 'Enhanced Trait',
                      'Adds tracking capability to rockets. Locks onto targets when aiming down sights. Increases blast radius.'),
            definition(inv[str(INTRINSIC)], INTRINSIC, 'Precision Frame', 'Intrinsic',
                      'This weapon fires small auto-tracking rockets. Rockets lock onto targets when aimed.')]
    require(inv[str(BASE)]['plug']['plugCategoryHash'] == 7906839
            and inv[str(INTRINSIC)]['plug']['plugCategoryHash'] == 1744546145,
            'Trait/intrinsic plug categories drift')
    rows, intrinsic_rows, proof, scans, direct, enhanced, rockets = [], [], [], [], [], [], []
    for w in selected:
        item = inv[str(w['bungieHash'])]
        require(item['hash'] == w['bungieHash'] and item['itemType'] == 3
                and not item['redacted'] and not item['blacklisted']
                and {k:v['value'] for k,v in item['stats']['stats'].items()} == w['stats'],
                'Selected official identity/stat mismatch: '+w['id'])
        require(item['equippingBlock']['ammoType'] == {'PRIMARY':1,'SPECIAL':2,'HEAVY':3}[w['ammo']],
                'Selected ammo mismatch: '+w['id'])
        sockets = item.get('sockets', {})
        trait_indexes = {i for c in sockets.get('socketCategories',[]) if c['socketCategoryHash']==TRAIT_CATEGORY for i in c['socketIndexes']}
        intrinsic_indexes = {i for c in sockets.get('socketCategories',[]) if c['socketCategoryHash']==INTRINSIC_CATEGORY for i in c['socketIndexes']}
        scan = {'id':w['id'],'hash':item['hash'],'family':cat[w['id']]['family'],
                'frame':cat[w['id']]['frame'],'examinedPools':[], 'directTrackingChoices':[]}
        for index, socket in enumerate(sockets.get('socketEntries',[])):
            initial = socket['singleInitialItemHash']
            direct_hashes = {initial, *[p['plugItemHash'] for p in socket.get('reusablePlugItems',[])]}
            if BASE in direct_hashes:
                row = {'id':w['id'],'hash':item['hash'],'socket':index,
                       'perkHash':BASE,'initialItemIsTracking':initial==BASE,
                       'reusableItemIsTracking':any(p['plugItemHash']==BASE for p in socket.get('reusablePlugItems',[]))}
                direct.append(row);scan['directTrackingChoices'].append(row)
            if ENHANCED in direct_hashes:
                enhanced.append({'id':w['id'],'socket':index,'source':'direct'})
            if initial == INTRINSIC:
                require(index in intrinsic_indexes and index==0 and w['id']=='pyroclastic_flow'
                        and item['hash']==1289324202 and cat[w['id']]['frame']=='precision'
                        and cat[w['id']]['family']=='rocket_launcher' and item['itemTypeDisplayName']=='Rocket Launcher'
                        and socket['socketTypeHash']==3956125808 and socket['reusablePlugSetHash']==6
                        and not socket.get('randomizedPlugSetHash'), 'Exact intrinsic socket proof mismatch')
                intrinsic_rows.append({'id':w['id'],'hash':item['hash'],'socket':0,
                                       'intrinsicHash':INTRINSIC,'proofMode':'initialIntrinsic'})
            for field in ('randomizedPlugSetHash','reusablePlugSetHash'):
                set_hash=socket.get(field)
                if not set_hash:
                    continue
                pool=pools[str(set_hash)]
                require(pool['hash']==set_hash and not pool['redacted'] and not pool['blacklisted'],
                        'Invalid selected referenced pool')
                entries=pool.get('reusablePlugItems',[])
                matches=[{'index':n,'item':e} for n,e in enumerate(entries) if e['plugItemHash']==BASE]
                scan['examinedPools'].append({'socket':index,'field':field,'plugSetHash':set_hash,
                    'isFakePlugSet':pool['isFakePlugSet'],'entryCount':len(entries),'baseMatches':matches})
                if any(e['plugItemHash']==ENHANCED for e in entries):
                    enhanced.append({'id':w['id'],'socket':index,'source':field,'plugSetHash':set_hash})
                rollable=[m for m in matches if m['item'].get('currentlyCanRoll') is True]
                if not rollable:
                    continue
                require(field=='randomizedPlugSetHash' and not pool['isFakePlugSet']
                        and index in trait_indexes and not w['exotic'] and item['inventory']['tierType']==5
                        and len(rollable)==1 and cat[w['id']]['family']=='rocket_launcher'
                        and item['itemTypeDisplayName']=='Rocket Launcher', 'Unsupported tracking availability proof')
                row={'id':w['id'],'hash':item['hash'],'socket':index,'perkHash':BASE,
                     'plugSetHash':set_hash,'proofMode':'randomized'}
                rows.append(row)
                proof.append({**row,'socketCategoryHash':TRAIT_CATEGORY,'socketEntry':socket,
                    'plugSetField':field,'isFakePlugSet':pool['isFakePlugSet'],'matchingEntries':rollable})
        scans.append(scan)
        if cat[w['id']]['family']=='rocket_launcher':
            require(w['id'] in ROCKETS, 'Unexpected selected rocket; review scope')
            h, frame, ih=ROCKETS[w['id']]
            require(item['hash']==h and cat[w['id']]['frame']==frame
                    and sockets['socketEntries'][0]['singleInitialItemHash']==ih
                    and 0 in intrinsic_indexes, 'Selected rocket frame mismatch')
            rockets.append({'id':w['id'],'hash':h,'frame':frame,'intrinsicHash':ih,
                            'intrinsicDefinition':inv[str(ih)]['displayProperties'],
                            'socketEntry':sockets['socketEntries'][0]})
    require(len(rows)==2 and {r['id']:(r['hash'],r['socket'],r['plugSetHash']) for r in rows}==EXPECTED,
            'Expected exact two randomized base Tracking Module sockets')
    require(intrinsic_rows==[{'id':'pyroclastic_flow','hash':1289324202,'socket':0,
                             'intrinsicHash':INTRINSIC,'proofMode':'initialIntrinsic'}],
            'Expected exactly one exact automatic intrinsic weapon')
    require({(r['id'],r['hash'],r['socket'],r['initialItemIsTracking'],r['reusableItemIsTracking']) for r in direct}
            =={('bad_omens',991314988,3,True,True),('bellowing_giant',2186258845,3,True,True)},
            'Direct choices differ from randomized proofs; inspect curated eligibility')
    require(not enhanced and len(rockets)==4, 'Enhanced/scope changed; review explicitly')
    evidence(data,'research1','https://www.bungie.net/en/Explore/Detail/DestinyInventoryItemDefinition/991314988',
             ['Tracking Module','Locks onto targets when aiming down sights.'])
    # Secondary report is preserved but deliberately NOT promoted to an exact runtime rule.
    evidence(data,'research1','https://www.light.gg/db/ja/items/3977735242/%E8%BF%BD%E8%B7%A1%E3%83%A2%E3%82%B8%E3%83%A5%E3%83%BC%E3%83%AB/',
             ['API ID: 3977735242','Tracking persists for 1 second','2024-02-29'])
    return defs,rows,intrinsic_rows,proof,scans,direct,rockets


def extract(root,data,pins):
    defs,rows,intrinsic_rows,proof,scans,direct,rockets=validate(data)
    facts={'requiresAim':True,'requiresAimSource':'Official intrinsic/trait descriptions',
           'continuousAimAfterLaunchRequired':None,'unknownSourceRules':UNKNOWN}
    resource={'stage':'W104',
        'intrinsic':{'hash':INTRINSIC,'name':'Precision Frame','type':'Intrinsic',
                     'requiresAim':True,'mechanicsSource':REF+'mechanics.json'},
        'perk':{'id':'tracking_module','hash':BASE,'enhancedHash':ENHANCED,
                'enhancedImplemented':False,'requiresAim':True,'mechanicsSource':REF+'mechanics.json'},
        'intrinsicWeapons':intrinsic_rows,'weapons':rows,
        'sourceRules':facts}
    mechanics={'stage':'W104','definitions':defs,'primarySourceFacts':facts,
        'primaryEvidence':[
          {'kind':'officialManifest','path':PINS['inventory']['path'],'definitionHash':INTRINSIC,
           'summary':'Exact Pyroclastic Flow initial Precision Frame intrinsic establishes aimed locking and auto-tracking rockets.'},
          {'kind':'officialManifest','path':PINS['inventory']['path'],'definitionHash':BASE,
           'summary':'Base Tracking Module establishes target locking while aiming down sights.'},
          {'kind':'officialBungieItemPage','url':'https://www.bungie.net/en/Explore/Detail/DestinyInventoryItemDefinition/991314988',
           'retrieval':'Pinned search excerpt; corroborates official manifest description, not numeric measurement.'}],
        'secondaryReportedEvidence':[
          {'url':'https://www.light.gg/db/ja/items/3977735242/%E8%BF%BD%E8%B7%A1%E3%83%A2%E3%82%B8%E3%83%A5%E3%83%BC%E3%83%AB/',
           'publisher':'light.gg / Clarity Community Research','primary':False,'updatedAt':'2024-02-29',
           'retrieval':'Pinned URL-bound search excerpt; direct English/localized HTTP fetch failed 402.',
           'reportedAimLossPersistenceSeconds':1,'reportedDiminishedPvpEffectiveness':True,
           'adoptedAsExactRuntimeRule':False,'measurementProtocolInspected':False,
           'summary':'Aimed enemy is reported as fired rocket target; aim-loss persistence is not in-flight homing duration. No tested lock acquisition time or angular guidance value is supplied.'}],
        'localPolicy':{'ownedBy':'Master integration, not this source profile',
                       'exactDestinyNumericsClaimed':False,'authoredParameters':None},
        'limitations':LIMITATIONS}
    scope={'stage':'W104','selectedCount':63,'rocketCount':4,'optionalTraitCount':2,
        'intrinsicCount':1,'randomizedCount':2,'fixedCuratedCount':0,
        'enhancedOptionsExcluded':[], 'definitions':defs,'optionalWeapons':proof,
        'intrinsicWeapons':intrinsic_rows,'rocketComparison':rockets,
        'directChoicesCorroboratingRandomizedOnly':direct,
        'allSelectedPoolScans':scans,
        'unsupportedOptionalIds':[r['id'] for r in data['selected'] if r['id'] not in EXPECTED],
        'policy':'Exact hash/socket/category/currentlyCanRoll/real randomized pool. No enhanced, family-wide defaults, curated-only inference, or same-name Precision Frame promotion.',
        'limitations':LIMITATIONS}
    path='/common/destiny2_content/json/en/DestinyInventoryItemDefinition-'+SUFFIX
    provenance={'stage':'W104','manifestVersion':VERSION,
        'manifestEndpoint':'https://www.bungie.net/Platform/Destiny2/Manifest/',
        'inventoryUrl':'https://www.bungie.net'+path,
        'plugSetsUrl':'https://www.bungie.net'+path.replace('DestinyInventoryItemDefinition-','DestinyPlugSetDefinition-'),
        'cacheFormat':'Pinned matching official JSON components, not a guessed SQLite schema.',
        'sourcePins':pins,'generator':SCRIPT,'generatorSha256':digest((root/SCRIPT).read_bytes()),
        'toolchain':{'minimumPython':'3.10','dependencies':'standard library only','generatorVersion':1,
                     'byteOrder':'Selected catalog order; UTF-8 JSON indent=2 newline'},
        'research':{'targetedQueries':8,'queryBound':8,'childToolsAvailable':False,'childWorkClaimed':False,
                    'directClarityRepositoryAttempt':'https://api.github.com/repos/Database-Clarity/Descriptions/contents returned 404; no data adopted.',
                    'sourcesAreUntrustedData':True,
                    'primaryMeasuredNumericsFound':False,'midflightLosLossRuleFound':False},
        'reproduce':'rtk proxy python3 '+SCRIPT+' --verify --self-test',
        'reproduceElsewhere':'rtk proxy python3 '+SCRIPT+' --output-root /tmp/w104-repro',
        'limitations':LIMITATIONS}
    return {TARGET:resource,REF+'mechanics.json':mechanics,REF+'socket-pools.json':scope,REF+'provenance.json':provenance}


def negative_fixtures(data):
    # Only mutation targets are copied; 199MB source is neither rewritten nor mutated.
    cases=[]
    def check(name, change):
        mutant=dict(data)
        change(mutant)
        try:
            validate(mutant)
        except (ValueError,KeyError,TypeError) as e:
            cases.append({'fixture':name,'status':'REJECTED','reason':str(e)})
        else:
            raise ValueError('Mutation fixture wrongly accepted: '+name)
    def pool_change(d,field,value):
        d['plugSets']=dict(d['plugSets']);p=copy.deepcopy(d['plugSets']['457210958'])
        if field=='currentlyCanRoll':
            next(e for e in p['reusablePlugItems'] if e['plugItemHash']==BASE)[field]=value
        else:p[field]=value
        d['plugSets']['457210958']=p
    check('randomized-canRoll-false',lambda d:pool_change(d,'currentlyCanRoll',False))
    check('fake-randomized-pool',lambda d:pool_change(d,'isFakePlugSet',True))
    def intrinsic_change(d):
        d['inventory']=dict(d['inventory']);i=copy.deepcopy(d['inventory']['1289324202'])
        i['sockets']['socketEntries'][0]['singleInitialItemHash']=216781713
        d['inventory']['1289324202']=i
    check('same-name-wrong-intrinsic-hash',intrinsic_change)
    def trait_kind(d):
        d['inventory']=dict(d['inventory']);i=copy.deepcopy(d['inventory'][str(BASE)])
        i['itemTypeDisplayName']='Enhanced Trait';d['inventory'][str(BASE)]=i
    check('base-definition-enhanced-type',trait_kind)
    def curated(d):
        d['inventory']=dict(d['inventory']);i=copy.deepcopy(d['inventory']['991314988'])
        s=i['sockets']['socketEntries'][3];s['reusablePlugSetHash']=s.pop('randomizedPlugSetHash')
        d['inventory']['991314988']=i
    check('curated-pool-not-randomized',curated)
    return cases


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--verify',action='store_true')
    parser.add_argument('--self-test',action='store_true')
    parser.add_argument('--root',type=Path,default=ROOT)
    parser.add_argument('--output-root',type=Path)
    args=parser.parse_args()
    try:
        require(not(args.verify and args.output_root),'--verify cannot write to --output-root')
        root=args.root.resolve();data,pins=load_sources(root);outputs=extract(root,data,pins)
        fixtures=negative_fixtures(data) if args.self_test else []
        for relative,value in outputs.items():
            content=encoded(value);path=(args.output_root or root)/relative
            if args.verify:require(path.read_bytes()==content,'Generated output differs: '+relative)
            else:path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(content)
        print(json.dumps({'stage':'W104','status':'VERIFY_PASS' if args.verify else 'GENERATED',
                          'selected':63,'optionalTrait':2,'intrinsic':1,
                          'outputs':list(outputs),'negativeFixtures':fixtures},indent=2))
    except (OSError,ValueError,KeyError,TypeError) as e:
        print('W104 extraction failed: '+str(e),file=sys.stderr);return 1
    return 0


if __name__=='__main__':
    raise SystemExit(main())
